#!/usr/bin/env python3
"""
钩子实现规则 R7：类名长度必须为质数
- 触发器：文件写入/编辑前
- 目标：类/类型
- 执行器：Semgrep（通过 Python 脚本模拟）
"""
import json
import sys
import re
from pathlib import Path

def is_prime(n):
    """检查数字是否为质数"""
    if n  <  2:
        return False
    if n  ==  2:
        return True
    if n  %  2  ==  0:
        return False
    for i in range(3, int(n  **  0.5)  +  1, 2):
        if n  %  i  ==  0:
            return False
    return True

def is_code_file(file_path):
    """检查文件是否为代码文件"""
    code_extensions  =  {
        '.py', '.js', '.ts', '.jsx', '.tsx', '.java', '.c', '.cpp', '.cc', '.cxx', '.h', '.hpp',
        '.cs', '.rb', '.go', '.rs', '.php', '.swift', '.kt', '.scala', '.clj', '.cljs',
        '.r', '.m', '.mm', '.pl', '.lua', '.vim', '.sh', '.bash', '.zsh', '.fish',
        '.yaml', '.yml', '.json', '.xml', '.html', '.css', '.scss', '.sass', '.less',
        '.sql', '.dockerfile', '.makefile', '.cmake', '.gradle', '.maven', '.sbt',
        '.groovy', '.dart', '.elm', '.haskell', '.hs', '.ml', '.ocaml', '.fs', '.fsx',
        '.erl', '.ex', '.exs', '.jl', '.nim', '.nims', '.zig', '.v', '.vhdl', '.verilog',
        '.sv', '.tcl', '.asm', '.s', '.proto', '.graphql', '.gql', '.thrift',
    }
    path  =  Path(file_path)
    return path.suffix.lower() in code_extensions

def check_class_names(content, file_path):
    """
    检查代码中的类名长度是否为质数。
    返回 (合格, 错误信息)
    """
    lines  =  content.split('\n')
    file_ext  =  Path(file_path).suffix.lower()

    if file_ext  ==  '.py':
        class_pattern  =  r'^\s*class\s+([A-Za-z_]\w*)\s*[\(:]'
    elif file_ext in ('.js', '.ts', '.jsx', '.tsx'):
        class_pattern  =  r'^\s*class\s+([A-Za-z_$]\w*)\s*[\{(]'
    elif file_ext  ==  '.java':
        class_pattern  =  r'(?:public|private)?\s+(?:abstract\s+)?class\s+([A-Za-z_]\w*)\s*[\{<]'
    elif file_ext in ('.c', '.cpp', '.cc', '.cxx', '.h', '.hpp'):
        class_pattern  =  r'(?:class|struct)\s+([A-Za-z_]\w*)\s*[\{;]'
    else:
        class_pattern  =  r'class\s+([A-Za-z_]\w*)\s*[\{(:]'

    for line_num, line in enumerate(lines, 1):
        stripped  =  line.lstrip()
        if stripped.startswith('#') or stripped.startswith('//'):
            continue

        matches  =  re.finditer(class_pattern, line)
        for match in matches:
            class_name  =  match.group(1)
            name_length  =  len(class_name)

            if not is_prime(name_length):
                return False, f"第 {line_num} 行：类名'{class_name}'长度为 {name_length}，不是质数。类名长度必须为质数（2, 3, 5, 7, 11, 13 等）"

    return True, None

try:
    input_data  =  json.load(sys.stdin)

    tool_name  =  input_data.get('tool_name', '')
    tool_input  =  input_data.get('tool_input', {})
    file_path  =  tool_input.get('file_path', '')

    if not file_path or tool_name not in ('Write', 'Edit', 'MultiEdit', 'NotebookEdit'):
        sys.exit(0)

    if not is_code_file(file_path):
        sys.exit(0)

    if tool_name  ==  'Write':
        content  =  tool_input.get('content', '')
    elif tool_name  ==  'Edit':
        content  =  tool_input.get('new_string', '')
    else:
        sys.exit(0)

    is_valid, error_msg  =  check_class_names(content, file_path)

    if not is_valid:
        sys.stderr.write(f"规则 R7 违反：{error_msg}。规则 R7：你所编写的代码文件内，所有类名的长度均需恰好为质数，不得有例外\n")
        sys.exit(2)

    sys.exit(0)

except Exception as e:
    sys.exit(0)
